function escapeHtml(str) {
  return normalizeUiCopy(String(str ?? ""))
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function createLocalId(prefix) {
  return `${prefix}_${Math.random().toString(36).substring(2, 11)}`;
}

function truncate(value, maxLength = 150) {
  const text = String(value ?? "").trim();
  if (!text) {
    return "";
  }

  return text.length > maxLength ? `${text.slice(0, maxLength - 3)}...` : text;
}

function truncateSentence(value, maxLength = 120) {
  const text = String(value ?? "").trim();
  if (!text) {
    return "";
  }

  const firstSentence = text.split(/(?<=[.!?])\s+/)[0]?.trim() || text;
  if (firstSentence.length <= maxLength) {
    return firstSentence;
  }

  const slice = firstSentence.slice(0, maxLength - 3);
  const boundary = slice.lastIndexOf(" ");
  const safeSlice = boundary > Math.floor(maxLength * 0.55) ? slice.slice(0, boundary) : slice;
  return `${safeSlice.trim()}...`;
}

function summarizeCompareCopy(value, maxLength = 88) {
  const text = String(value ?? "").replace(/\s+/g, " ").trim();
  if (!text) {
    return "";
  }

  const firstSentence = text.split(/(?<=[.!?])\s+/)[0]?.trim() || text;
  if (firstSentence.length <= maxLength) {
    return firstSentence;
  }

  const clauseCandidates = firstSentence
    .split(/\s+(?:and|but|while|so)\s+/i)
    .map((part) => part.trim().replace(/[,:;]+$/, ""))
    .filter(Boolean);
  const shortClause = clauseCandidates.find((part) => part.length >= 18 && part.length <= maxLength);
  if (shortClause) {
    return /[.!?]$/.test(shortClause) ? shortClause : `${shortClause}.`;
  }

  return truncateSentence(firstSentence, maxLength);
}

function normalizeStageDisplayName(name, fallback = "Unnamed stage") {
  const cleanName = String(name ?? "")
    .trim()
    .replace(/^Stage\s+\d+\s*(?:[/:-]\s*)?/i, "")
    .trim();
  return cleanName || fallback;
}

function summarizeCompareCommitment(stageModel, stepCount = 0) {
  const estimateParts = String(stageModel?.cycleEstimate || "")
    .split("/")
    .map((part) => part.trim())
    .filter(Boolean);
  const activeWindow = estimateParts.find((part) => /min/i.test(part));
  if (activeWindow) {
    return activeWindow;
  }
  if (stepCount) {
    return `${stepCount}-step opening`;
  }
  return "Cadence varies";
}

function formatStageCompactLabel(sequenceIndex, name) {
  const cleanName = String(name ?? "").trim();
  return cleanName ? `Stage ${sequenceIndex} / ${cleanName}` : `Stage ${sequenceIndex}`;
}

function formatScheduledStepLabel(stepCount) {
  if (!stepCount) {
    return "Cadence varies";
  }
  return `${stepCount} ordered step${stepCount === 1 ? "" : "s"}`;
}

function resolvePlanTheme(plan) {
  return {
    color: plan.theme?.color || "#4FD1C5",
    icon: normalizeUiCopy(plan.theme?.icon || "PL"),
  };
}

